        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    # Matrix exponentiation using binary exponentiation
    def matrix_pow(M, exp, mod):
        # Start with identity matrix
        result = [[1, 0], [0, 1]]
        base = [row[:] for row in M]  # Deep copy

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            exp //= 2

        return result

    # Compute M^n mod p
    result_matrix = matrix_pow(M, n, mod)

    # Sum all entries
    total = sum(result_matrix[i][j] for i in range(2) for j in range(2))

